def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/astronomy/input/STORM-AI/warmup/v2/OMNI2/omni2-wu334-20161022_to_20161024.csv'
    # Some environments mount data under an implicit working dir; fall back to glob to locate exact filename
    import os, glob
    if not os.path.exists(path):
        matches = glob.glob('data/astronomy/input/STORM-AI/warmup/v2/OMNI2/omni2-wu334-*.csv')
        if len(matches) == 1:
            path = matches[0]
        else:
            raise FileNotFoundError(f'Expected {path} or single glob match; got {len(matches)} matches')
    return pd.read_csv(path)

